42	func (db *db) getLocalCluster() *appv1.Cluster {
43		initLocalCluster.Do(func() {
44			info, err := db.kubeclientset.Discovery().ServerVersion()
45			if err == nil {
46				ver, verErr := version.ParseGeneric(info.GitVersion)
47				if verErr == nil {
48					localCluster.Info.ServerVersion = ver.String()
49				} else {
50					log.Warnf("Failed to parse Kubernetes server version: %v", verErr)
51				}
52				localCluster.Info.ConnectionState = appv1.ConnectionState{Status: appv1.ConnectionStatusSuccessful}
53			} else {
54				localCluster.Info.ConnectionState = appv1.ConnectionState{
55					Status:  appv1.ConnectionStatusFailed,
56					Message: err.Error(),
57				}
58			}
59		})
60		cluster := localCluster.DeepCopy()
61		now := metav1.Now()
62		cluster.Info.ConnectionState.ModifiedAt = &now
63		return cluster
64	}
