149	func (db *db) WatchClusters(ctx context.Context,
150		handleAddEvent func(cluster *appv1.Cluster),
151		handleModEvent func(oldCluster *appv1.Cluster, newCluster *appv1.Cluster),
152		handleDeleteEvent func(clusterServer string),
153	) error {
154		inClusterEnabled, err := db.settingsMgr.IsInClusterEnabled()
155		if err != nil {
156			log.Warnf(errCheckingInClusterEnabled, "WatchClusters", err)
157		}
158		localCls := db.getLocalCluster()
159		if inClusterEnabled {
160			localCls, err = db.GetCluster(ctx, appv1.KubernetesInternalAPIServerAddr)
161			if err != nil {
162				return fmt.Errorf("could not get local cluster: %w", err)
163			}
164			handleAddEvent(localCls)
165		}
166	
167		db.watchSecrets(
168			ctx,
169			common.LabelValueSecretTypeCluster,
170	
171			func(secret *corev1.Secret) {
172				cluster, err := SecretToCluster(secret)
173				if err != nil {
174					log.Errorf("could not unmarshal cluster secret %s", secret.Name)
175					return
176				}
177				if cluster.Server == appv1.KubernetesInternalAPIServerAddr {
178					if inClusterEnabled {
179						// change local cluster event to modified, since it cannot be added at runtime
180						handleModEvent(localCls, cluster)
181						localCls = cluster
182					}
183					return
184				}
185				handleAddEvent(cluster)
186			},
187	
188			func(oldSecret *corev1.Secret, newSecret *corev1.Secret) {
189				oldCluster, err := SecretToCluster(oldSecret)
190				if err != nil {
191					log.Errorf("could not unmarshal cluster secret %s", oldSecret.Name)
192					return
193				}
194				newCluster, err := SecretToCluster(newSecret)
195				if err != nil {
196					log.Errorf("could not unmarshal cluster secret %s", newSecret.Name)
197					return
198				}
199				if newCluster.Server == appv1.KubernetesInternalAPIServerAddr {
200					localCls = newCluster
201				}
202				handleModEvent(oldCluster, newCluster)
203			},
204	
205			func(secret *corev1.Secret) {
206				if string(secret.Data["server"]) == appv1.KubernetesInternalAPIServerAddr && inClusterEnabled {
207					// change local cluster event to modified, since it cannot be deleted at runtime, unless disabled.
208					newLocalCls := db.getLocalCluster()
209					handleModEvent(localCls, newLocalCls)
210					localCls = newLocalCls
211				} else {
212					handleDeleteEvent(string(secret.Data["server"]))
213				}
214			},
215		)
216	
217		return err
218	}
