to the cluster's server URL.\n// Applications whose destination name is ambiguous (resolves to more than one\n// server URL) are not counted.\nfunc (c *clusterInfoUpdater) getUpdatedClusterInfo(ctx context.Context, apps []*appv1.Application, cluster appv1.Cluster, clusterInfo *appv1.ClusterInfo, now metav1.Time) *appv1.ClusterInfo {\n\tif clusterInfo == nil {\n\t\tclusterInfo = &appv1.ClusterInfo{}\n\t}\n\tclusterInfo.ConnectionState.ModifiedAt = &now\n\n\tvar appCount int64\n\tfor _, a := range apps {\n\t\tif c.projGetter != nil {\n\t\t\tproj, err := c.projGetter(a)\n\t\t\tif err != nil || !proj.IsAppNamespacePermitted(a, c.namespace) {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t}\n\t\tdestCluster, err := argo.GetDestinationCluster(ctx, a.Spec.Destination, c.db)\n\t\tif err != nil {\n\t\t\tcontinue\n\t\t}\n\t\tif destCluster.Server == cluster.Server {\n\t\t\tappCount++\n\t\t}\n\t}\n\tclusterInfo.ApplicationsCount = appCount\n\n\treturn clusterInfo\n}\n", "numLines": 70, "startLine": 116, "totalLines": 195}}
